head.b:skin:
/* =========================================================
   Economic Insight theme
   Date hierarchy: year > month > week > day
   ========================================================= */

:root {
  --bg: #ffffff;
  --bg-soft: #f6f7f9;
  --text: #1c1e21;
  --text-soft: #6b7280;
  --line: #e5e7eb;
  --accent: #2456c4;
  --accent-soft: #eef2fb;
  --radius: 10px;
  --font: -apple-system, BlinkMacSystemFont, "Apple SD Gothic Neo",
          "Pretendard", "Noto Sans KR", "Malgun Gothic", "Segoe UI", sans-serif;
}

@media (prefers-color-scheme: dark) {
  :root {
    --bg: #16181c;
    --bg-soft: #1e2126;
    --text: #e8eaed;
    --text-soft: #9aa0a6;
    --line: #2d3138;
    --accent: #7ba0f0;
    --accent-soft: #232a3a;
  }
}

* { box-sizing: border-box; }

html { -webkit-text-size-adjust: 100%; }

body {
  margin: 0;
  background: var(--bg);
  color: var(--text);
  font-family: var(--font);
  font-size: 16px;
  line-height: 1.7;
  word-break: keep-all;
}

a { color: var(--accent); text-decoration: none; }
a:hover { text-decoration: underline; }

img { max-width: 100%; height: auto; }

/* ---------- layout ---------- */

.site {
  max-width: 1080px;
  margin: 0 auto;
  padding: 0 20px;
}

.site-layout {
  display: grid;
  grid-template-columns: minmax(0, 1fr) 280px;
  gap: 48px;
  align-items: start;
  padding: 32px 0 64px;
}

/* ---------- header ---------- */

.site-header {
  padding: 40px 0 24px;
  border-bottom: 1px solid var(--line);
  text-align: center;
}

.site-title {
  margin: 0;
  font-size: 1.7rem;
  font-weight: 800;
  letter-spacing: -0.02em;
}

.site-title a { color: var(--text); }
.site-title a:hover { text-decoration: none; color: var(--accent); }

.site-desc {
  margin: 6px 0 0;
  color: var(--text-soft);
  font-size: 0.95rem;
}

/* ---------- timeline: year > month > week > day ---------- */

.page-title {
  font-size: 1.15rem;
  font-weight: 700;
  margin: 0 0 20px;
  padding-bottom: 12px;
  border-bottom: 1px solid var(--line);
  color: var(--text-soft);
}

.tl-year { margin-bottom: 8px; }

.tl-year-h {
  position: sticky;
  top: 0;
  z-index: 3;
  margin: 0 0 4px;
  padding: 10px 0 8px;
  background: var(--bg);
  font-size: 1.5rem;
  font-weight: 800;
  letter-spacing: -0.02em;
  border-bottom: 2px solid var(--text);
}

.tl-month { margin: 20px 0 4px; padding-left: 4px; }

.tl-month-h {
  margin: 0 0 8px;
  font-size: 1.15rem;
  font-weight: 700;
  color: var(--text);
}

.tl-week {
  margin: 12px 0 12px 8px;
  padding-left: 16px;
  border-left: 2px solid var(--line);
}

.tl-week-h {
  display: inline-block;
  margin: 0 0 8px;
  padding: 2px 10px;
  font-size: 0.8rem;
  font-weight: 700;
  color: var(--accent);
  background: var(--accent-soft);
  border-radius: 999px;
}

.tl-day { margin: 0 0 14px; }

.tl-day-h {
  margin: 0 0 6px;
  font-size: 0.85rem;
  font-weight: 600;
  color: var(--text-soft);
}

.tl-day-h::before {
  content: '';
  display: inline-block;
  width: 7px;
  height: 7px;
  margin-right: 8px;
  border-radius: 50%;
  background: var(--accent);
  vertical-align: 1px;
}

/* ---------- post cards ---------- */

.post-card {
  padding: 14px 16px;
  margin: 0 0 8px;
  background: var(--bg-soft);
  border: 1px solid var(--line);
  border-radius: var(--radius);
  transition: border-color 0.15s ease;
}

.post-card:hover { border-color: var(--accent); }

.post-card-link { display: block; color: inherit; }
.post-card-link:hover { text-decoration: none; }

.post-card-title {
  margin: 0 0 4px;
  font-size: 1.05rem;
  font-weight: 700;
  letter-spacing: -0.01em;
}

.post-card:hover .post-card-title { color: var(--accent); }

.post-card-snippet {
  margin: 0;
  font-size: 0.88rem;
  color: var(--text-soft);
  line-height: 1.6;
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
  overflow: hidden;
}

.post-card-date {
  display: block;
  margin-top: 6px;
  font-size: 0.78rem;
  color: var(--text-soft);
}

/* ---------- single post ---------- */

.post-single .post-title {
  margin: 8px 0 12px;
  font-size: 1.8rem;
  font-weight: 800;
  line-height: 1.35;
  letter-spacing: -0.02em;
}

.post-date-line {
  display: flex;
  align-items: center;
  gap: 10px;
  flex-wrap: wrap;
  padding-bottom: 20px;
  margin-bottom: 28px;
  border-bottom: 1px solid var(--line);
  font-size: 0.9rem;
  color: var(--text-soft);
}

.post-week {
  padding: 1px 10px;
  font-size: 0.78rem;
  font-weight: 700;
  color: var(--accent);
  background: var(--accent-soft);
  border-radius: 999px;
}

.post-body {
  font-size: 1.02rem;
  line-height: 1.85;
}

.post-body h2 { font-size: 1.35rem; margin: 2em 0 0.6em; }
.post-body h3 { font-size: 1.15rem; margin: 1.6em 0 0.5em; }
.post-body p { margin: 0 0 1.1em; }
.post-body blockquote {
  margin: 1.2em 0;
  padding: 10px 18px;
  border-left: 3px solid var(--accent);
  background: var(--bg-soft);
  border-radius: 0 var(--radius) var(--radius) 0;
  color: var(--text-soft);
}
.post-body pre {
  padding: 14px;
  overflow-x: auto;
  background: var(--bg-soft);
  border: 1px solid var(--line);
  border-radius: var(--radius);
  font-size: 0.88rem;
}
.post-body table {
  border-collapse: collapse;
  width: 100%;
  margin: 1.2em 0;
  font-size: 0.92rem;
}
.post-body th, .post-body td {
  border: 1px solid var(--line);
  padding: 8px 12px;
  text-align: left;
}
.post-body th { background: var(--bg-soft); }

/* 다크 모드: 편집기가 본문에 심어둔 인라인 색(검정 글자, 흰 배경 등)이
   어두운 배경과 충돌하지 않도록 본문 색을 테마 색으로 강제 통일 */
@media (prefers-color-scheme: dark) {
  .post-body, .post-body * { color: var(--text) !important; }
  .post-body a, .post-body a * { color: var(--accent) !important; }
  .post-body * { background-color: transparent !important; }
  .post-body blockquote { background: var(--bg-soft) !important; color: var(--text-soft) !important; }
  .post-body pre { background: var(--bg-soft) !important; }
  .post-body th { background: var(--bg-soft) !important; }
}

/* ---------- pager ---------- */

.pager {
  display: flex;
  justify-content: space-between;
  gap: 12px;
  margin-top: 36px;
  padding-top: 20px;
  border-top: 1px solid var(--line);
  font-size: 0.92rem;
}

.pager a {
  padding: 8px 14px;
  border: 1px solid var(--line);
  border-radius: var(--radius);
  color: var(--text);
}

.pager a:hover {
  border-color: var(--accent);
  color: var(--accent);
  text-decoration: none;
}

.pager-home { color: var(--text-soft) !important; border: none !important; }

/* ---------- sidebar archive ---------- */

.site-side {
  position: sticky;
  top: 20px;
  font-size: 0.9rem;
}

.archive-box {
  padding: 18px;
  background: var(--bg-soft);
  border: 1px solid var(--line);
  border-radius: var(--radius);
}

.archive-title {
  margin: 0 0 4px;
  font-size: 0.95rem;
  font-weight: 800;
}

.archive-sub {
  margin: 0 0 12px;
  font-size: 0.76rem;
  color: var(--text-soft);
}

.archive-tree summary {
  cursor: pointer;
  padding: 4px 0;
  font-weight: 700;
  list-style: none;
}

.archive-tree summary::-webkit-details-marker { display: none; }

.archive-tree summary::before {
  content: '\25B8';
  display: inline-block;
  width: 14px;
  color: var(--text-soft);
  transition: transform 0.15s ease;
}

.archive-tree details[open] > summary::before { transform: rotate(90deg); }

.ar-count {
  margin-left: 4px;
  font-size: 0.75rem;
  font-weight: 600;
  color: var(--text-soft);
}

.ar-month { margin-left: 14px; }
.ar-month > summary { font-weight: 600; }

.ar-week { margin: 4px 0 8px 28px; }

.ar-week-h {
  margin: 6px 0 2px;
  font-size: 0.72rem;
  font-weight: 700;
  color: var(--accent);
}

.ar-day-group { margin: 2px 0 6px; }

.ar-day {
  font-size: 0.75rem;
  color: var(--text-soft);
  margin: 2px 0;
}

.ar-day-group ul {
  margin: 0;
  padding-left: 14px;
  list-style: none;
}

.ar-day-group li {
  margin: 1px 0;
  line-height: 1.5;
  font-size: 0.85rem;
}

.ar-day-group a { color: var(--text); }
.ar-day-group a:hover { color: var(--accent); }

.archive-empty { color: var(--text-soft); font-size: 0.85rem; }

/* ---------- comments ---------- */

.comments { margin-top: 48px; }

.comments-h {
  font-size: 1.1rem;
  font-weight: 700;
  margin: 0 0 4px;
  padding-bottom: 10px;
  border-bottom: 1px solid var(--line);
}

.comment {
  padding: 12px 0;
  border-bottom: 1px solid var(--line);
}

.comment-author { margin: 0 0 4px; font-weight: 700; font-size: 0.9rem; }
.comment-time { font-weight: 400; color: var(--text-soft); font-size: 0.78rem; margin-left: 8px; }
.comment-body { font-size: 0.95rem; line-height: 1.65; }
.comment-body p { margin: 0 0 0.6em; }
.comment-empty { color: var(--text-soft); font-size: 0.88rem; padding: 10px 0; }

.comment-form-wrap { margin-top: 18px; }

.comment-frame {
  width: 100%;
  border: 1px solid var(--line);
  border-radius: var(--radius);
  background: #ffffff;
}

.comment-alt {
  margin: 6px 0 0;
  font-size: 0.78rem;
  text-align: right;
}

/* ---------- error / empty ---------- */

.error-page, .empty-state {
  text-align: center;
  padding: 80px 0;
  color: var(--text-soft);
}

.error-page h1 { font-size: 1.3rem; color: var(--text); }

/* ---------- footer ---------- */

.site-footer {
  padding: 24px 0 40px;
  border-top: 1px solid var(--line);
  text-align: center;
  font-size: 0.8rem;
  color: var(--text-soft);
}

.site-footer .widget { margin: 0; }

/* ---------- responsive ---------- */

@media (max-width: 900px) {
  .site-layout {
    grid-template-columns: 1fr;
    gap: 32px;
  }
  .site-side { position: static; order: 2; }
  .site-main { order: 1; }
  .site-header { padding: 28px 0 18px; }
  .post-single .post-title { font-size: 1.45rem; }
}

body.script:
//
(function () {
  'use strict';

  var DAY_NAMES = ['일', '월', '화', '수', '목', '금', '토'];

  // 주차 규칙: 1~7일 = 1주차, 8~14일 = 2주차, ...
  function weekOfMonth(d) {
    return Math.ceil(d.getDate() / 7);
  }

  function el(tag, cls, text) {
    var n = document.createElement(tag);
    if (cls) n.className = cls;
    if (text) n.textContent = text;
    return n;
  }

  function hasClass(node, cls) {
    return (' ' + node.className + ' ').indexOf(' ' + cls + ' ') !== -1;
  }

  function fetchJson(path, cb) {
    var xhr = new XMLHttpRequest();
    xhr.open('GET', path, true);
    xhr.onreadystatechange = function () {
      if (xhr.readyState !== 4) return;
      if (xhr.status !== 200) { cb(null); return; }
      try {
        var data = JSON.parse(xhr.responseText);
        cb((data.feed && data.feed.entry) || []);
      } catch (e) {
        cb(null);
      }
    };
    xhr.send();
  }

  function altLink(entry) {
    var link = '';
    (entry.link || []).forEach(function (l) {
      if (l.rel === 'alternate') link = l.href;
    });
    return link;
  }

  /* ---------- 공통: 연 > 월 > 주 > 일 그룹핑 ---------- */
  // items: [{date: Date, node: Element}] (최신순)
  function makeGrouped(items) {
    var frag = document.createDocumentFragment();
    var curY = null, curM = null, curW = null, curD = null;
    var ySec = null, mSec = null, wSec = null, dPosts = null;

    items.forEach(function (item) {
      var d = item.date;
      if (!d || isNaN(d.getTime())) { frag.appendChild(item.node); return; }
      var y = d.getFullYear();
      var m = d.getMonth() + 1;
      var w = weekOfMonth(d);
      var day = d.getDate();

      if (y !== curY) {
        ySec = el('section', 'tl-year');
        ySec.appendChild(el('h2', 'tl-year-h', y + '년'));
        frag.appendChild(ySec);
        curY = y; curM = null; curW = null; curD = null;
      }
      if (m !== curM) {
        mSec = el('section', 'tl-month');
        mSec.appendChild(el('h3', 'tl-month-h', m + '월'));
        ySec.appendChild(mSec);
        curM = m; curW = null; curD = null;
      }
      if (w !== curW) {
        wSec = el('section', 'tl-week');
        wSec.appendChild(el('h4', 'tl-week-h', w + '주차'));
        mSec.appendChild(wSec);
        curW = w; curD = null;
      }
      if (day !== curD) {
        var dSec = el('section', 'tl-day');
        dSec.appendChild(el('h5', 'tl-day-h', day + '일 (' + DAY_NAMES[d.getDay()] + ')'));
        dPosts = el('div', 'tl-day-posts');
        dSec.appendChild(dPosts);
        wSec.appendChild(dSec);
        curD = day;
      }
      dPosts.appendChild(item.node);
    });

    return frag;
  }

  /* ---------- 1. 목록: 서버가 출력한 카드를 그룹핑 ---------- */
  function buildTimeline() {
    var timeline = document.getElementById('timeline');
    if (!timeline) return;
    var cards = Array.prototype.slice.call(timeline.querySelectorAll('.post-card'));

    if (!cards.length) {
      var empty = el('div', 'empty-state');
      if (hasClass(document.body, 'view-error')) {
        empty.appendChild(el('p', null, '페이지를 찾을 수 없습니다.'));
        var home = el('a', null, '홈으로 돌아가기');
        home.href = '/';
        empty.appendChild(home);
      } else {
        empty.appendChild(el('p', null, '게시글이 없습니다.'));
      }
      timeline.appendChild(empty);
      return;
    }

    var items = cards.map(function (card) {
      var t = card.querySelector('.post-card-date');
      if (t) t.style.display = 'none'; // 그룹 헤더와 중복되는 개별 날짜 숨김
      return { date: new Date(card.getAttribute('data-date')), node: card };
    });

    timeline.innerHTML = '';
    timeline.appendChild(makeGrouped(items));
  }

  /* ---------- 2. 개별 글: "M월 N주차" 배지 ---------- */
  function fillWeekBadges() {
    var spans = document.querySelectorAll('.js-week');
    for (var i = 0; i < spans.length; i++) {
      var d = new Date(spans[i].getAttribute('data-date'));
      if (isNaN(d.getTime())) continue;
      spans[i].textContent = (d.getMonth() + 1) + '월 ' + weekOfMonth(d) + '주차';
    }
  }

  /* ---------- 댓글: 게시글의 댓글 피드를 불러와 표시 ---------- */
  function fmtDateTime(d) {
    var h = d.getHours(), min = d.getMinutes();
    return d.getFullYear() + '. ' + (d.getMonth() + 1) + '. ' + d.getDate() + '. '
      + (h < 10 ? '0' + h : h) + ':' + (min < 10 ? '0' + min : min);
  }

  function loadComments() {
    var sec = document.getElementById('comments');
    if (!sec || sec.getAttribute('data-loaded')) return;
    var postId = sec.getAttribute('data-post-id');
    if (!postId) return;
    sec.setAttribute('data-loaded', '1');
    var list = sec.querySelector('.comment-list');
    if (!list) return;

    fetchJson('/feeds/' + postId + '/comments/default?alt=json&max-results=200', function (entries) {
      list.innerHTML = '';
      if (entries === null) {
        list.appendChild(el('p', 'comment-empty', '댓글을 불러오지 못했습니다.'));
        return;
      }
      if (!entries.length) {
        list.appendChild(el('p', 'comment-empty', '아직 댓글이 없습니다. 첫 댓글을 남겨보세요.'));
        return;
      }
      entries.forEach(function (entry) {
        var item = el('div', 'comment');
        var author = (entry.author && entry.author[0] && entry.author[0].name && entry.author[0].name.$t) || '익명';
        var head = el('p', 'comment-author', author);
        var d = new Date(entry.published.$t);
        if (!isNaN(d.getTime())) head.appendChild(el('span', 'comment-time', fmtDateTime(d)));
        item.appendChild(head);
        var body = el('div', 'comment-body');
        body.innerHTML = (entry.content && entry.content.$t) || '';
        item.appendChild(body);
        list.appendChild(item);
      });
    });
  }

  /* ---------- 3. 예비 렌더링: 위젯이 본문을 못 그리면 피드로 직접 그림 ---------- */
  function buildFallback() {
    var box = document.getElementById('content-fallback');
    if (!box) return;
    if (hasClass(document.body, 'view-error')) return;

    if (hasClass(document.body, 'view-item')) {
      if (document.querySelector('.post-single')) return; // 서버 렌더링 정상
      fetchJson('/feeds/posts/default?alt=json&max-results=150', function (entries) {
        if (!entries) return;
        var here = location.pathname;
        for (var i = 0; i < entries.length; i++) {
          var link = altLink(entries[i]);
          var path;
          try { path = new URL(link).pathname; } catch (e) { continue; }
          if (path !== here) continue;

          var entry = entries[i];
          var d = new Date(entry.published.$t);
          var art = el('article', 'post post-single');
          var head = el('header', 'post-header');
          head.appendChild(el('h1', 'post-title', entry.title.$t || '(제목 없음)'));
          var dateLine = el('div', 'post-date-line');
          dateLine.appendChild(el('time', 'post-date',
            d.getFullYear() + '년 ' + (d.getMonth() + 1) + '월 ' + d.getDate() + '일 (' + DAY_NAMES[d.getDay()] + ')'));
          dateLine.appendChild(el('span', 'post-week', (d.getMonth() + 1) + '월 ' + weekOfMonth(d) + '주차'));
          head.appendChild(dateLine);
          art.appendChild(head);
          var body = el('div', 'post-body');
          body.innerHTML = (entry.content && entry.content.$t) || (entry.summary && entry.summary.$t) || '';
          art.appendChild(body);
          box.appendChild(art);

          // 예비 렌더링에서도 댓글 표시/입력 지원 (피드 항목 id에서 블로그/글 번호 추출)
          var ids = ((entry.id && entry.id.$t) || '').match(/blog-(\d+)\.post-(\d+)/);
          if (ids) {
            var sec = el('section', 'comments');
            sec.id = 'comments';
            sec.setAttribute('data-post-id', ids[2]);
            sec.appendChild(el('h2', 'comments-h', '댓글'));
            var list = el('div', 'comment-list');
            list.appendChild(el('p', 'comment-empty', '댓글을 불러오는 중…'));
            sec.appendChild(list);
            var wrap = el('div', 'comment-form-wrap');
            var ifr = document.createElement('iframe');
            ifr.className = 'comment-frame';
            ifr.src = 'https://www.blogger.com/comment/frame/' + ids[1] + '/' + ids[2] + '?po=true&hl=ko';
            ifr.width = '100%';
            ifr.height = '260';
            ifr.frameBorder = '0';
            wrap.appendChild(ifr);
            sec.appendChild(wrap);
            box.appendChild(sec);
            loadComments();
          }

          var nav = el('nav', 'pager');
          var home = el('a', 'pager-home', '목록');
          home.href = '/';
          nav.appendChild(home);
          box.appendChild(nav);
          return;
        }
      });
    } else {
      if (document.getElementById('timeline')) return; // 서버 렌더링 정상
      fetchJson('/feeds/posts/summary?alt=json&max-results=500', function (entries) {
        if (!entries || !entries.length) return;
        var items = [];
        entries.forEach(function (entry) {
          var link = altLink(entry);
          var d = new Date(entry.published.$t);
          if (!link || isNaN(d.getTime())) return;
          var card = el('article', 'post-card');
          var a = el('a', 'post-card-link');
          a.href = link;
          a.appendChild(el('h2', 'post-card-title', entry.title.$t || '(제목 없음)'));
          var snippet = ((entry.summary && entry.summary.$t) || '').replace(/\s+/g, ' ').trim();
          if (snippet.length > 130) snippet = snippet.slice(0, 130) + '…';
          if (snippet) a.appendChild(el('p', 'post-card-snippet', snippet));
          card.appendChild(a);
          items.push({ date: d, node: card });
        });
        items.sort(function (a, b) { return b.date - a.date; });
        box.className = 'timeline';
        box.appendChild(makeGrouped(items));
      });
    }
  }

  /* ---------- 4. 사이드바: 전체 글 보관함 트리 ---------- */
  function buildArchive() {
    var box = document.getElementById('archive-tree');
    if (!box) return;
    fetchJson('/feeds/posts/summary?alt=json&max-results=500', function (entries) {
      if (entries === null) {
        box.innerHTML = '';
        box.appendChild(el('p', 'archive-empty', '보관함을 불러오지 못했습니다.'));
        return;
      }
      renderArchive(box, entries);
    });
  }

  function renderArchive(box, entries) {
    box.innerHTML = '';
    if (!entries.length) {
      box.appendChild(el('p', 'archive-empty', '게시글이 없습니다.'));
      return;
    }

    var posts = [];
    entries.forEach(function (entry) {
      var link = altLink(entry);
      var d = new Date(entry.published.$t);
      if (!link || isNaN(d.getTime())) return;
      posts.push({ title: entry.title.$t || '(제목 없음)', url: link, date: d });
    });

    posts.sort(function (a, b) { return b.date - a.date; });

    var years = [];
    function getOrPush(arr, key, make) {
      for (var i = 0; i < arr.length; i++) {
        if (arr[i].key === key) return arr[i];
      }
      var node = make();
      node.key = key;
      arr.push(node);
      return node;
    }

    posts.forEach(function (p) {
      var y = p.date.getFullYear();
      var m = p.date.getMonth() + 1;
      var w = weekOfMonth(p.date);
      var day = p.date.getDate();
      var yNode = getOrPush(years, y, function () { return { count: 0, months: [] }; });
      yNode.count++;
      var mNode = getOrPush(yNode.months, m, function () { return { count: 0, weeks: [] }; });
      mNode.count++;
      var wNode = getOrPush(mNode.weeks, w, function () { return { days: [] }; });
      var dNode = getOrPush(wNode.days, day, function () { return { dow: DAY_NAMES[p.date.getDay()], posts: [] }; });
      dNode.posts.push(p);
    });

    var nowYear = new Date().getFullYear();

    years.forEach(function (yNode) {
      var yDet = el('details', 'ar-year');
      if (yNode.key === nowYear) yDet.open = true;
      var ySum = el('summary', null, yNode.key + '년');
      ySum.appendChild(el('span', 'ar-count', yNode.count + '개'));
      yDet.appendChild(ySum);

      yNode.months.forEach(function (mNode, mi) {
        var mDet = el('details', 'ar-month');
        if (yNode.key === nowYear && mi === 0) mDet.open = true;
        var mSum = el('summary', null, mNode.key + '월');
        mSum.appendChild(el('span', 'ar-count', mNode.count + '개'));
        mDet.appendChild(mSum);

        mNode.weeks.forEach(function (wNode) {
          var wDiv = el('div', 'ar-week');
          wDiv.appendChild(el('p', 'ar-week-h', wNode.key + '주차'));

          wNode.days.forEach(function (dNode) {
            var dg = el('div', 'ar-day-group');
            dg.appendChild(el('p', 'ar-day', dNode.key + '일 (' + dNode.dow + ')'));
            var ul = el('ul');
            dNode.posts.forEach(function (p) {
              var li = el('li');
              var a = el('a', null, p.title);
              a.href = p.url;
              li.appendChild(a);
              ul.appendChild(li);
            });
            dg.appendChild(ul);
            wDiv.appendChild(dg);
          });

          mDet.appendChild(wDiv);
        });

        yDet.appendChild(mDet);
      });

      box.appendChild(yDet);
    });
  }

  function init() {
    buildTimeline();
    fillWeekBadges();
    buildFallback();
    buildArchive();
    loadComments();
  }

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', init);
  } else {
    init();
  }
})();
//
